contract InvMutTest {
    C c;
    address deployer;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Try to call migrateTo with some address `to` and optional Ether parameter (unused by migrateTo).
    // We require nothing about msg.value; we will not send Ether when calling migrateTo.
    function run(address to) public payable {
        // record contract balance before
        uint256 beforeBal = address(c).balance;

        bool migratedReverted;
        // call migrateTo and catch revert
        c.migrateTo(to); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            migratedReverted = true;
        } else {
            migratedReverted = false;
        }

        uint256 afterBal = address(c).balance;

        // General rule: if migrateTo did not revert, then c's balance is now zero (full balance transferred out).
        // If it reverted, we make no claim. This captures that migrateTo moves the entire balance when caller is creator.
        assert(migratedReverted || afterBal == 0);
    }

    // receive in case c.transfer sends Ether to this contract during migrateTo
    receive() external payable {}
}

